{
  "correction_rules": [
    "Adjust forecasts downward when sentiment history shows no positive signal (sentiment=0.00) and model overestimates prices.",
    "Reduce forecast magnitude by 5-10% if recent history shows mean reversion toward lower prices (e.g., 3-5 consecutive days of declining prices).",
    "If model spikes upward after a recent low, apply a lag correction: reduce forecast by 10-20% for the next 3-5 days to avoid overshoot.",
    "When sentiment history includes a single positive signal (sentiment=0.25), slightly increase forecast to reflect potential upward momentum, but cap at 10% above prior peak.",
    "For long-term (30-day) forecasts, apply a smoothing filter: if true outcome deviates >15% from 10-day moving average, adjust forecast toward that average.",
    "If model consistently underestimates prices during early part of the forecast horizon (e.g., first 5 days), apply a bias correction: add 3-5% to forecast for those days."
  ]
}
